<style>
body{margin:0;background:#081225;color:#fff;font-family:Segoe UI,Arial,sans-serif}
.hero{background:#000;padding:0}.hero img{width:100%;display:block}
.container{padding:20px}
.mod{padding:14px 20px;border-radius:14px;font-size:30px;font-weight:700;margin:30px 0 15px}
.futsal{background:#2563eb}.hand{background:#16a34a}.queimada{background:#dc2626}
.group{text-align:center;color:#cbd5e1;font-size:22px;margin:16px 0;padding-bottom:8px;border-bottom:1px solid #334155}
.cards{display:flex;flex-wrap:wrap;justify-content:center;gap:20px}
.card{width:400px;max-width:100%;background:#1e293b;border-radius:18px;padding:16px;text-align:center}
.j{font-size:26px;font-weight:800;color:#fbbf24}
.info{font-size:15px;color:#cbd5e1;margin:6px 0}
.p{display:flex;justify-content:center;align-items:center;gap:14px;margin-top:12px}
.t{font-size:20px;font-weight:700;flex: 1;text-align: center;word-break: break-word}
.r{font-size:44px;font-weight:900;flex-shrink: 0}
.status{display:inline-block;background:#475569;padding:6px 12px;border-radius:999px;font-size:12px;margin-top:10px}
.status_check{background:#3CB371;}
.banner{margin:35px 0;background:linear-gradient(135deg,#172554,#1e3a8a);border-left:8px solid #facc15;padding:28px;border-radius:18px;text-align:center}
.banner img{max-width:100%;max-height:500px;display:block;margin:0 auto;border-radius:12px}</style>
